n_cmd_targetClient.signature:
// targetClient 按规范目标取得一个可用的 agentd 客户端。
//
// 返回的 cleanup 关闭本次可能建立的 relay 隧道，调用方必须调用（直连形态
// 是 no-op）。target 为空或登记到本机的 loopback 地址都走 LocalEndpoint；
// 未登记名称仍原样拒绝。
func targetClient(target string) (*client.Client, func(), error) {
	canonical, err := canonicalCLITarget(target)
	if err != nil {
		return nil, func() {}, err
	}
	if canonical == "" {
		addr, token, err := LocalEndpoint()
		if err != nil {
			return nil, func() {}, err
		}
		slog.Info("CLI 采用本机客户端", "target", target, "canonical_target", canonical)
		return client.New(addr, token), func() {}, nil
	}
	slog.Info("CLI 采用远端客户端", "target", canonical, "canonical_target", canonical)
	return newTargetClientNamed(canonical)
}

n_cmd_writeDispatchPointer.signature:
// writeDispatchPointer 派发成功后落里程碑指针行（B156.2 欠账 #11 岔口八）。
// 具名函数而非内联进 RunE 闭包：C6 的指针引用白名单守卫按「所在函数」归属，
// 落在匿名闭包里归属不到真正的调用点。成功路径才写（ViaTemplate 失败零半
// 状态）；写失败不打断派发主流程——指针是房间面信号，错误仅日志（判据二，
// TestCardDispatchPointerFailureDoesNotInterrupt）。
func writeDispatchPointer(st *ledger.Store, id, nodeLabel string) {
	if perr := roomPointer(roomServiceFor(st), id, dispatchPointerBody(id, nodeLabel)); perr != nil {
		slog.Warn("派发指针落账失败", "card", id, "cause", perr)
	}
}

n_agentd_Server_cardStepInFlight.signature:
func (s *Server) cardStepInFlight(cardID string) bool {
	s.cardStepMu.Lock()
	defer s.cardStepMu.Unlock()
	return s.cardStepFlight[cardID]
}

n_agentd_Server_claimCardStep.signature:
func (s *Server) claimCardStep(cardID string) bool {
	s.cardStepMu.Lock()
	defer s.cardStepMu.Unlock()
	if s.cardStepFlight[cardID] {
		return false
	}
	s.cardStepFlight[cardID] = true
	return true
}

n_agentd_Server_compensateStep.signature:
// compensateStep 回收一次已取得 task id 的失败派发。具名入口（原为内联闭包），
// 依赖声明收窄到 stopReclaimClient；只回收，不改原始错误。
func (s *Server) compensateStep(ctx context.Context, cl stopReclaimClient, cardID, target, taskID string) error {
	s.log.Info("agentd 派发失败补偿开始", "card", cardID, "target", target, "task", taskID)
	if err := cl.StopAndReclaim(ctx, taskID); err != nil {
		s.log.Error("agentd 派发失败补偿失败", "card", cardID, "target", target, "task", taskID, "cause", err)
		return err
	}
	s.log.Info("agentd 派发失败补偿完成", "card", cardID, "target", target, "task", taskID)
	return nil
}

n_agentd_Server_disciplineTargetCap.signature:
// disciplineTargetCap 读目标机的 DisciplinesSupported。
//
// 本机（local / 本机 / 本机 hostname）就是当前进程：能力位与 Status 上报同源
// （当前二进制恒 true）。"local" 不是 config.Targets 里的远程机，pool.For 会
// 稳定报未登记；把 nil 当不支持会让本机点火被 B229 拒发闸误杀（B299 真机）。
// 远程机仍走探活；失败保持 nil，按不支持处置。生产派发走 resolveStepDiscipline
// 的探活失败硬红路径；本函数只服务本机短路单测。
func (s *Server) disciplineTargetCap(target string) *bool {
	if isLocalMachine(target) {
		yes := true
		return &yes
	}
	cl, err := s.pool.For(target)
	if err != nil {
		s.log.Warn("环节派发前取得目标机客户端失败", "target", target, "cause", err)
		return nil
	}
	status, serr := probeStatus(context.Background(), cl)
	if serr != nil {
		s.log.Warn("环节派发前能力位探活失败", "target", target, "cause", serr)
		return nil
	}
	return status.DisciplinesSupported
}

n_agentd_Server_pushWorkBranchOrigin.signature:
// pushWorkBranchOrigin 在持有工作分支的那台机把分支推到 origin。
// 走任务仓库的 git push，失败由调用方打 needs_human。
func (s *Server) pushWorkBranchOrigin(ctx context.Context, target, branch, taskID string) error {
	if strings.TrimSpace(branch) == "" {
		return fmt.Errorf("工作分支名为空，无法 push origin")
	}
	if strings.TrimSpace(taskID) == "" {
		return fmt.Errorf("没有任务 id，无法在执行机 push origin %s", branch)
	}
	canonical := s.CanonicalTarget(target)
	cl, err := s.clientForTarget(canonical)
	if err != nil {
		s.log.Error("取得 push origin 客户端失败", "target", target, "canonical_target", canonical,
			"branch", branch, "task", taskID, "cause", err)
		return fmt.Errorf("取得 %s 客户端去 push origin: %w", target, err)
	}
	return s.pushWorkBranchVia(ctx, cl, canonical, branch, taskID)
}

n_agentd_Server_pushWorkBranchVia.signature:
// pushWorkBranchVia 在持有工作分支的机器上执行一次 git push。具名入口，
// 依赖声明收窄到 runClient；canonical target 由调用方归一后传入。
func (s *Server) pushWorkBranchVia(ctx context.Context, cl runClient, target, branch, taskID string) error {
	cmd := "git push origin " + strconv.Quote(branch)
	s.log.Info("推送工作分支到 origin", "target", target, "branch", branch, "task", taskID)
	out, code, runErr := cl.Run(ctx, taskID, cmd)
	if runErr != nil {
		s.log.Error("推送工作分支请求失败", "target", target, "branch", branch,
			"task", taskID, "cause", runErr)
		return runErr
	}
	if code != 0 {
		s.log.Error("推送工作分支非零退出", "target", target, "branch", branch,
			"task", taskID, "exit", code)
		return fmt.Errorf("git push origin %s 退出码 %d：%s", branch, code, strings.TrimSpace(out))
	}
	s.log.Info("工作分支已推到 origin", "target", target, "branch", branch, "task", taskID)
	return nil
}

n_agentd_Server_releaseCardStep.signature:
func (s *Server) releaseCardStep(cardID string) {
	s.cardStepMu.Lock()
	delete(s.cardStepFlight, cardID)
	s.cardStepMu.Unlock()
}

n_agentd_Server_resolveStepDiscipline.signature:
// resolveStepDiscipline 是环节派发的缝 1 收口（B229 契约 §2.2）：按与 ViaTemplate
// 完全相同的裁决顺序算出有效（角色名，目标机），绑账本 lookup 与能力位探活各一次，
// 经 discipline.ResolveDispatch 产出随派发下发的正文三元组。未点名模板同样过闸，
// 产物是纯平台层正文、版本 0（§3.1：拒发闸覆盖一切带正文派发）。
//
// 为什么探活失败不能按不支持处置：能力位缺席(nil)只表示探活成功后对端未上报，
// 网络/认证错误必须保留 cause 并停止派发；只有 nil/false 能力位才进入升级拒发。
func (s *Server) resolveStepDiscipline(node ledger.NodeDef, reqTarget string) (discipline.ResolvedDiscipline, string, error) {
	name, target, err := ledgerstep.PreflightDiscipline(s.ledger, node.Template, node.Override.Discipline, reqTarget)
	if err != nil {
		return discipline.ResolvedDiscipline{}, "", err
	}
	target = s.CanonicalTarget(target)
	if isLocalMachine(target) {

		target = ""
	}
	cl, err := s.clientForTarget(target)
	if err != nil {
		s.log.Error("环节纪律探活取得客户端失败", "node", node.Name, "target", target,
			"canonical_target", target, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	status, err := probeStatus(context.Background(), cl)
	if err != nil {
		s.log.Error("环节纪律探活失败", "node", node.Name, "target", target,
			"canonical_target", target, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	s.log.Info("环节纪律探活完成", "node", node.Name, "target", target,
		"canonical_target", target, "cap_absent", status.DisciplinesSupported == nil)
	cap := status.DisciplinesSupported
	lookup := func(n string) (int, string, error) {
		d, gerr := s.ledger.GetDiscipline(n, 0)
		if gerr != nil {
			return 0, "", gerr
		}
		return d.Version, d.Body, nil
	}
	res, err := discipline.ResolveDispatch(lookup, discipline.DisciplineRef{Name: name},
		s.conf().PlatformInvariantsEnabled(), cap)
	if err != nil {
		s.log.Warn("环节派发被拒发闸拦下", "node", node.Name, "target", target,
			"discipline", name, "cap_absent", cap == nil, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf("环节 %s 派发前纪律解析失败: %w", node.Name, err)
	}
	s.log.Info("环节派发纪律正文已就绪", "node", node.Name, "target", target,
		"discipline", name, "version", res.Version, "bytes", len(res.Text))
	return res, target, nil
}

n_agentd_Server_runStep.signature:
// runStep 是 runStepFn 的生产实现：跑环节并把结果记进日志。
//
// 为什么错误只进日志不往上抛：调用它的 goroutine 没有上游。环节的成败
// 由 ledgerstep 落进卡的事件流，那是界面看得见的地方；日志是排查时的第二现场。
func (s *Server) runStep(ctx context.Context, runner *ledgerstep.StepRunner, cardID, node string) {
	outcome, err := runner.Run(ctx, cardID, node)
	if err != nil {
		s.log.Error("节点失败", "card", cardID, "node", node, "cause", err)
		return
	}
	s.log.Info("节点结束", "card", cardID, "node", node,
		"action", string(outcome.Action), "reason", outcome.Reason)
}

n_agentd_Server_startCardStep.signature:
// startCardStep 装配并异步启动一个卡节点。
//
// 参数：cardID 是卡号；req 是已完成 actor 归一和字段校验的规范请求。
// 返回：同卡已有在飞节点时返回 errStepInFlight；其它前置校验错误原样返回；成功
// 只表示 goroutine 已启动，不表示节点完成。后台结束时必须释放既有卡槽位。
//
// 为什么必须异步：审阅环节会阻塞到被派出去的 task 跑到回合终态——几分钟到
// 几十分钟，executor 挂在 waiting_answer 时更久。HTTP 请求扛不住这个时长，
// 界面靠已有的卡事件流看进展。
//
// 注意：返回 nil 不代表环节成功，只代表它启动了。成败落在卡的事件流上。
func (s *Server) startCardStep(cardID string, req proto.CardStepReq) error {
	if !s.claimCardStep(cardID) {
		return fmt.Errorf("%w: %s 的 %s 节点正在运行", errStepInFlight, cardID, req.Step)
	}
	// B229 缝 1：解析在同步段完成——拒发发生在 goroutine 启动之前，槽位当场
	// 释放，HTTP 层拿到的是带升级指引的可行动错误。有效（角色名，目标机）与
	// ViaTemplate 的裁决同序（共用 PreflightDiscipline）。
	node, err := ledgerstep.ResolveNode(s.ledger, cardID, req.Step)
	if err != nil {
		s.releaseCardStep(cardID)
		return err
	}
	if node.Override.Squad != "" {
		if named := strings.TrimSpace(req.Target); named != "" {
			s.releaseCardStep(cardID)
			s.log.Warn("小队节点拒绝点名机器", "card", cardID, "node", node.Name,
				"squad", node.Override.Squad, "target", named)
			return fmt.Errorf("节点 %s 已绑小队 %q，禁止 --target %s；由 Admit 选机器",
				node.Name, node.Override.Squad, named)
		}
		if named := strings.TrimSpace(req.Executor); named != "" {
			s.releaseCardStep(cardID)
			s.log.Warn("小队节点拒绝点名执行器", "card", cardID, "node", node.Name,
				"squad", node.Override.Squad, "executor", named)
			return fmt.Errorf("节点 %s 已绑小队 %q，禁止 --executor %s；由 Admit 选载体 CLI",
				node.Name, node.Override.Squad, named)
		}
	}
	// B156.3 K2：节点绑小队时编制域先选择本次派发身份（解析层插在纪律解析之前——
	// 有效目标机要等 Binding 出来才知道，能力位探活必须打 Binding.Target）。
	// 三种同步结局：admitted→Binding 三元组接管覆盖继续装配；queued→已持久
	// 入队，本轮以排队形态结束（释放槽位返回 nil，不起 goroutine、无 task、
	// 卡事件流零写入）；error→受理失败上浮（HTTP 非 202）。Select 只读，不需要
	// 回滚执行名额。
	binding := scheduling.Binding{}
	if node.Override.Squad != "" {
		outcome := squadDispatchAdmitted
		binding, outcome, err = s.admitSquadStep(cardID, req, node)
		if err != nil {
			s.releaseCardStep(cardID)
			return err
		}
		if outcome == squadDispatchQueued {
			s.releaseCardStep(cardID)
			return nil
		}
	}
	target := req.Target
	if binding.Target != "" {
		target = binding.Target
	}
	var dispatchHomeDir *string
	if binding.Carrier != "" {
		// 指针指向本次装配的稳定副本，避免下层误读可变 registry 对象；值本身
		// 仍逐字节传递，目标 executor 才负责把它放进进程环境。
		homeDir := binding.HomeDir
		dispatchHomeDir = &homeDir
	}
	resolved, target, err := s.resolveStepDiscipline(node, target)
	if err != nil {
		s.releaseCardStep(cardID)
		s.log.Warn("卡节点冻结身份后装配失败，未释放执行占用", "card", cardID,
			"node", req.Step, "squad", binding.Squad, "carrier", binding.Carrier,
			"error_kind", "assembly", "cause", err)
		return err
	}
	host, _ := os.Hostname()
	runner := &ledgerstep.StepRunner{
		St: s.ledger, Session: req.Actor,
		RunHolder: fmt.Sprintf("run:%s#%d#%d", host, os.Getpid(), time.Now().UnixNano()),
		Dispatcher: &ledgerstep.Dispatcher{
			St: s.ledger, Transport: s.stepTransport, Actor: req.Actor,
			// agentd 补偿借用 Server 持有的 client pool；不复制 target/relay
			// 选路，也不关闭池，只回收已取得 task id 的失败派发。
			Compensate: func(ctx context.Context, target, taskID string) error {
				cl, err := s.clientForTarget(target)
				if err != nil {
					s.log.Error("agentd 派发失败补偿创建 client 失败", "card", cardID, "target", target, "task", taskID, "cause", err)
					return err
				}
				return s.compensateStep(ctx, cl, cardID, target, taskID)
			},
			HomeDir:           dispatchHomeDir,
			Carrier:           binding.Carrier,
			Squad:             binding.Squad,
			FrozenTarget:      binding.Target,
			DisciplineText:    resolved.Text,
			DisciplineVersion: resolved.Version,
			NormalizeTarget:   s.CanonicalTarget,
		},
		Clients: func(target string) (ledgerstep.StepClient, error) {
			return s.clientForTarget(target)
		},
		Target:   target,
		Executor: req.Executor,
		Model:    req.Model,
		Extra:    req.Extra,
		PublishWorkBranch: func(ctx context.Context, target, branch, taskID string) error {
			return s.pushWorkBranchOrigin(ctx, target, branch, taskID)
		},
	}
	s.log.Info("卡节点装配完成", "card", cardID, "node", req.Step,
		"actor", req.Actor, "target", req.Target, "canonical_target", target,
		"frozen_target", binding.Target, "executor", req.Executor,
		"model", req.Model, "run_holder", runner.RunHolder,
		"has_extra", strings.TrimSpace(req.Extra) != "")
	if binding.Squad != "" {
		// Binding 三元组接管本次派发的有效覆盖（解析层语义，plan §D2）：
		// runner 字段是 dispatchNodeWithGate 的最高优先级来源，Binding 值恒
		// 非空（Target/Executor 由载体必填字段保证），模板缺省从此够不着。
		runner.Target = binding.Target
		runner.Executor = binding.Executor
		runner.Model = binding.Model
	}
	go func() {
		defer s.releaseCardStep(cardID)
		s.log.Info("卡节点回合开始", "card", cardID, "node", req.Step,
			"squad", binding.Squad, "carrier", binding.Carrier)
		s.runStepFn(context.Background(), runner, cardID, req.Step)
		s.log.Info("卡节点回合返回", "card", cardID, "node", req.Step,
			"squad", binding.Squad, "carrier", binding.Carrier,
			"occupancy_owner", "task_terminal", "card_slot_owner", "card_step")
	}()
	return nil
}

