n_agentd_Server_handleContinue.signature:
// handleContinue 向任务续发修改指令（要求任务处于 waiting_review）。
//
// 错误映射：任务不存在 404；状态不允许续接 409（manager 返回 store.ErrBadTransit）；
// executor 运行态已丢失 409（executor.ErrTaskNotRunning，agentd 可能重启过，提示
// 重新派发）。
func (s *Server) handleContinue(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("continue 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("continue 请求到达但 manager 未注入", "task", taskID)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req continueRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		s.log.Warn("continue 请求体解析失败", "task", taskID, "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {instructions}"})
		return
	}
	if req.Instructions == "" {
		s.log.Warn("continue 指令为空", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "instructions 不能为空"})
		return
	}
	if err := s.mgr.Continue(r.Context(), taskID, req.Instructions); err != nil {
		s.writeManagerError(w, taskID, "续发指令", err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

n_agentd_Server_handleDispatch.signature:
// handleDispatch 派发一个新任务，返回创建后的任务（state=running）。
//
// 流程：解析请求体 → 冻结身份准入或普通接收者准备链 → 接收机必须是载体登记机
// → manager.Dispatch（建任务/写 plan/启动 executor/进 running）。带 Carrier 的
// 请求必须使用已冻结的物理身份；Receiver 只作为审计字段，不能再次选择载体。
func (s *Server) handleDispatch(w http.ResponseWriter, r *http.Request) {
	s.log.Info("dispatch 请求", "method", r.Method, "path", r.URL.Path,
		"remote_addr", r.RemoteAddr)
	if s.mgr == nil {
		s.log.Warn("dispatch 请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req dispatchRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, 4<<20)).Decode(&req); err != nil {
		s.log.Warn("dispatch 请求体解析失败", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {project_id, plan_b64, ...}"})
		return
	}
	s.log.Info("dispatch 请求身份", "project", req.ProjectID, "receiver", req.Receiver,
		"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
		"frozen_target", req.FrozenTarget,
		"executor", req.Executor, "model", req.Model, "home_dir_set", req.HomeDir != nil)
	var binding scheduling.Binding
	var resolved scheduling.ResolvedReceiver
	var err error
	if req.Carrier != "" {
		if s.scheduling == nil {
			err = errors.New("编制域服务未装配（SetupAutomation 未执行）")
		} else if req.HomeDir == nil {
			err = fmt.Errorf("%w: 冻结请求必须明确携带 home_dir（空串表示目标机主 HOME）", scheduling.ErrInvalid)
			s.log.Warn("dispatch 冻结身份缺少 home_dir", "project", req.ProjectID,
				"receiver", req.Receiver, "carrier", req.Carrier, "squad", req.Squad,
				"target", req.Target, "error_kind", "frozen_home_dir_missing", "cause", err)
		} else {
			homeDir := *req.HomeDir
			// B398：有冻结字段用冻结字段建 Binding（快照优先），缺席时回落
			// req.Target（旧发送方逐字兼容）。显式空串不静默回落——按快照丢失
			// 交给 AdmitFrozen 判据拒掉，让发送方 bug 可见。
			frozenTarget := req.Target
			if req.FrozenTarget != nil {
				frozenTarget = *req.FrozenTarget
			}
			binding, err = s.scheduling.AdmitFrozen(scheduling.Binding{
				Squad: req.Squad, Carrier: req.Carrier, Target: frozenTarget,
				Executor: req.Executor, Model: req.Model, HomeDir: homeDir,
			})
			s.log.Info("dispatch 冻结身份准入", "project", req.ProjectID, "receiver", req.Receiver,
				"carrier", req.Carrier, "squad", req.Squad, "route_target", req.Target,
				"frozen_target", frozenTarget,
				"executor", req.Executor, "model", req.Model, "error_kind", "frozen_admit")
		}
	} else if req.Squad != "" {
		err = fmt.Errorf("%w: 冻结小队请求缺少 carrier", scheduling.ErrInvalid)
	} else {
		overlay := scheduling.PhysicalOverlay{Machine: req.Target, CLI: req.Executor, HomeDir: req.HomeDir}
		binding, resolved, err = s.prepareReceiverBinding(req.Receiver, overlay, req.Model)
		s.log.Info("dispatch 普通身份准入", "project", req.ProjectID, "receiver", req.Receiver,
			"resolved_name", resolved.Name, "resolved_kind", string(resolved.Kind),
			"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
			"executor", binding.Executor, "model", binding.Model, "error_kind", "ordinary_admit")
	}
	if err != nil {
		s.log.Warn("dispatch 身份准入失败", "project", req.ProjectID, "receiver", req.Receiver,
			"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
			"error_kind", "admit", "cause", err)
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released := false
	defer func() {
		if !released && binding.Carrier != "" && s.scheduling != nil {
			if relErr := s.scheduling.Release(binding.Squad, binding.Carrier); relErr != nil {
				s.log.Error("dispatch 失败释放占用失败", "project", req.ProjectID,
					"squad", binding.Squad, "carrier", binding.Carrier, "cause", relErr)
			}
		}
	}()
	home := binding.HomeDir
	var homePtr *string
	if req.Carrier != "" || home != "" {
		homePtr = &home
	}
	s.log.Info("dispatch 任务身份快照已组装", "project", req.ProjectID,
		"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
		"executor", binding.Executor, "home_dir_set", homePtr != nil)
	// B233.27：准入只核「请求 vs 登记」。现网登记名常是 targets 键（linux-01），
	// 不能只用 IsLocalMachine（它把 linux-01 当远端）。CanonicalTarget 空串=本机。
	if canon := s.CanonicalTarget(binding.Target); canon != "" {
		err = fmt.Errorf("%w: 载体登记机 %s 不是当前接收机", errReceiverNotCarrierMachine, binding.Target)
		s.log.Warn("dispatch 被拒：接收机不是载体登记机", "project", req.ProjectID,
			"carrier", binding.Carrier, "registered_target", binding.Target,
			"canonical_target", canon, "error_kind", "receiver_not_carrier_machine", "cause", err)
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	task, err := s.mgr.Dispatch(r.Context(), orchestration.DispatchReq{
		ProjectID: req.ProjectID, ProjectName: req.ProjectName,
		PlanB64: req.PlanB64, PlanName: req.PlanName, Target: binding.Target,
		Prompt: req.Prompt, Name: req.Name, Receiver: req.Receiver, Squad: binding.Squad, Carrier: binding.Carrier,
		Executor: binding.Executor, Discipline: req.Discipline, Model: binding.Model,
		HomeDir:           homePtr,
		DisciplineText:    req.DisciplineText,
		DisciplineVersion: req.DisciplineVersion,
		Branch:            req.Branch, NewBranch: req.NewBranch, Base: req.Base,
		ResolveDefaultBase: req.ResolveDefaultBase,
		LocalBaseBranch:    req.LocalBaseBranch,
		Worktree:           req.Worktree, NewWorktree: req.NewWorktree, BaseCommit: req.BaseCommit,
	})
	if err != nil {
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released = true // 成功后由 T4 的任务终态钩子释放占用
	s.log.Info("dispatch 完成", "task", task.ID, "state", task.State, "carrier", task.Carrier,
		"squad", binding.Squad, "target", binding.Target, "executor", binding.Executor)
	writeJSON(w, http.StatusOK, task)
}

