// Dispatch 派发一个新任务到 agentd 执行。
//
// 参数：
//   - opts: 派发参数（仓库/计划/执行者/分支/工作区等，见 DispatchOpts）
//
// 返回：
//   - 创建后的任务（state=running）；服务端启动 executor 失败时返回错误
func (c *Client) Dispatch(ctx context.Context, opts DispatchOpts) (*proto.Task, error) {
	body := map[string]any{
		"project_id": opts.ProjectID, "project_name": opts.ProjectName,
		"plan_b64": opts.PlanB64, "plan_name": opts.PlanName, "target": opts.Target,
		"prompt": opts.Prompt, "name": opts.Name, "executor": opts.Executor, "model": opts.Model,
		"discipline":         opts.Discipline,
		"discipline_text":    opts.DisciplineText,
		"discipline_version": opts.DisciplineVersion,
		"branch":             opts.Branch, "new_branch": opts.NewBranch, "base": opts.Base,
		"resolve_default_base": opts.ResolveDefaultBase,
		"local_base_branch":    opts.LocalBaseBranch,
		"worktree":             opts.Worktree, "new_worktree": opts.NewWorktree, "base_commit": opts.BaseCommit,
	}
	if opts.Receiver != "" {
		body["receiver"] = opts.Receiver
	}
	if opts.Carrier != "" {
		body["carrier"] = opts.Carrier
	}
	if opts.Squad != "" {
		body["squad"] = opts.Squad
	}
	if opts.HomeDir != nil {
		body["home_dir"] = *opts.HomeDir
	}
	if opts.FrozenTarget != "" {
		body["frozen_target"] = opts.FrozenTarget
	}
	c.log().Info("Dispatch 进入", "url", c.baseURL, "relay", c.relayBacked,
		"executor", opts.Executor, "target", opts.Target, "carrier", opts.Carrier, "squad", opts.Squad,
		"home_dir_set", opts.HomeDir != nil, "prompt_runes", len([]rune(opts.Prompt)))
	resp, err := c.do(ctx, http.MethodPost, "/api/tasks", body)
	if err != nil {
		c.log().Error("Dispatch 失败", "url", c.baseURL, "cause", err)
		return nil, fmt.Errorf("dispatch 请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		err := c.httpError("dispatch", resp)
		c.log().Error("Dispatch 失败", "url", c.baseURL, "cause", err)
		return nil, err
	}
	var task proto.Task
	if err := json.NewDecoder(resp.Body).Decode(&task); err != nil {
		err := fmt.Errorf("解析 dispatch 响应: %w", err)
		c.log().Error("Dispatch 失败", "url", c.baseURL, "cause", err)
		return nil, err
	}
	c.log().Info("Dispatch 完成", "url", c.baseURL, "task", task.ID, "state", task.State)
	return &task, nil
}

