// 注意：
//   - 命令非零退出不返回错误，退出码经 exitCode 表达；超时被杀时 exitCode=124
//   - 只有执行未发生（启动失败/超时/请求失败）才返回错误
func (c *Client) Run(ctx context.Context, taskID, cmd string) (stdout string, exitCode int, err error) {
	resp, err := c.do(ctx, http.MethodPost, "/api/tasks/"+taskID+"/run",
		map[string]string{"cmd": cmd})
	if err != nil {
		return "", 0, fmt.Errorf("run 请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", 0, c.httpError("run", resp)
	}
	var out struct {
		Stdout		string	`json:"stdout"`
		ExitCode	int	`json:"exit_code"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", 0, fmt.Errorf("解析 run 响应: %w", err)
	}
	return out.Stdout, out.ExitCode, nil
}

n_client_Client_Stop.signature:
// Stop 主动中止任务：停 executor、作废挂起工单、任务落 failed。
//
// 参数：
//   - taskID: 待中止的任务 ID
//
// 返回：
//   - worktreeRemoved: 响应体 worktree_removed 如实回传——true=本次删除了
//     managed worktree，false=用户自带 worktree / 原地模式（没删）；响应体缺字段
//     （旧版 agentd）按 false 处理。CLI 据此打印与行为一致的提示，不猜
//   - 任务不存在（404）或已是终态（409）时返回错误
func (c *Client) Stop(ctx context.Context, taskID string) (worktreeRemoved bool, err error) {
	c.log().Info("Stop 进入", "url", c.baseURL, "relay", c.relayBacked, "task", taskID)
	resp, err := c.do(ctx, http.MethodPost, "/api/tasks/"+taskID+"/stop", nil)
	if err != nil {
		c.log().Error("Stop 失败", "url", c.baseURL, "task", taskID, "cause", err)
		return false, fmt.Errorf("中止任务请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		err = c.httpError("中止任务", resp)
		c.log().Error("Stop 失败", "url", c.baseURL, "task", taskID, "cause", err)
		return false, err
	}
	var body struct {
		WorktreeRemoved bool `json:"worktree_removed"`
	}
	_ = json.NewDecoder(resp.Body).Decode(&body)
	c.log().Info("Stop 完成", "task", taskID, "worktree_removed", body.WorktreeRemoved)
	return body.WorktreeRemoved, nil
}

n_client_Client_StreamEventsOnce.signature:
// StreamEventsOnce 建立一次事件流连接，把收到的每一帧交给 onEvent，直到连接
// 断开或 ctx 取消。**不读写任何 cursor 文件，不做重连**。
//
// 参数：
//   - taskID: 任务 id（必须是完整 UUID）
//   - fromSeq: 起始 seq（开区间）；调用方自己持有水位
//   - onEvent: 每帧回调；返回错误即中止本次连接
//
// 为什么必须有这个「无 cursor」变体：FollowEvents / WaitEvent 把水位存在
// ~/.handoff/cursors/<agentd 地址>/<task>，那是**审核者本机**的状态。agentd 做事件镜像时
// 跑在同一台机器上，若复用带 cursor 的路径，agentd 的镜像与人手敲的
// handoff wait 会互相推进对方的水位——一方吃掉另一方的事件，且极难归因。
// 镜像的水位属于 mirror_events 表，不属于文件系统。
//
// 注意：单次连接、不重连。退避与重连策略由调用方（镜像订阅循环）决定，
// 它的节奏（300ms→×2→10s）与审核者 CLI 的（1s→60s）刻意不同。
func (c *Client) StreamEventsOnce(ctx context.Context, taskID string, fromSeq int64,
	onEvent func(proto.Event) error) error {
	c.log().Debug("镜像事件流建立", "addr", c.baseURL, "task", taskID, "from_seq", fromSeq)

	return c.streamOnce(ctx, taskID, fromSeq, func() time.Time { return time.Time{} }, onEvent)
}

n_client_Client_WaitEvent.signature:
// WaitEvent 阻塞等待任务的下一个事件：跳过 progress（除非 all=true），
// 拿到首个可动作事件即返回并把 cursor 写盘；断线指数退避 1s→2s→…→60s
// 无限重连，ctx 取消才退出。
//
// cursor 语义（事件不丢不重的根基）：
//   - 每次调用开始时从 <游标根>/cursors/<agentd>/<task> 读取上次交付事件的 seq，
//     连接 WS 时以 from_seq=cursor 补拉断线期间产生的事件
//   - 返回首个可动作事件时把 cursor 原子写盘为该事件的 seq；被跳过的 progress
//     事件不推进 cursor（下次调用会重新收到并再次跳过，重复跳过无副作用）
//   - 因此每条可动作事件恰好交付一次（不重），cursor 之后的事件断线后一条不丢（不丢）
//
// 为什么 progress 不唤醒：progress 是高频、无需人工动作的状态播报（如「正在运行」），
// 若用它唤醒，wait 会在每次进度变化时把协调者叫醒做无意义的一次「看-忽略」；
// 协调者只需在真正需要决策的事件（question/permission_request/completed/failed/stalled）
// 到达时被唤醒。需要全量事件流时显式传 all=true。
//
// 永久性失败（不重试）：握手 400/401/403（配置错误）与任务不存在（PolicyViolation
// close）立即返回错误——退避重连只为瞬时故障设计，见 isPermanent 的 why。
//
// 参数：
//   - taskID: 要等待的任务 ID
//   - all: true 时不做类型过滤，第一个到达的事件即返回
//
// 返回：
//   - 首个可动作事件；ctx 取消时返回 ctx.Err()（context.Canceled/DeadlineExceeded）；
//     永久性失败时返回对应的错误（不做退避）
func (c *Client) WaitEvent(ctx context.Context, taskID string, all bool) (*proto.Event, error) {
	fromSeq := c.readCursor(taskID)

	backoff := c.wsInitialBackoff
	for attempt := 1; ; attempt++ {
		start := time.Now()
		ev, err := c.waitOnce(ctx, taskID, fromSeq, all)
		lived := time.Since(start)
		if err == nil {
			if werr := c.writeCursor(taskID, ev.Seq); werr != nil {

				c.log().Warn("cursor 写盘失败", "task", taskID, "seq", ev.Seq, "cause", werr)
			}

			if ev.Type == proto.EventTypeArchived {
				c.DropCursor(taskID)
			}
			return ev, nil
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}

		if isPermanent(err) {
			c.log().Error("wait 永久失败，不再重试", "addr", c.baseURL, "task", taskID, "cause", err)
			return nil, err
		}

		c.log().Info("WS 连接断开，等待后重连", "addr", c.baseURL, "task", taskID,
			"attempt", attempt, "next_backoff_seconds", int(backoff.Seconds()), "cause", err)

		if lived >= c.wsStableAfter {
			backoff = c.wsInitialBackoff
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(backoff):
		}
		if lived < c.wsStableAfter {
			backoff *= 2
			if backoff > c.wsMaxBackoff {
				backoff = c.wsMaxBackoff
			}
		}
	}
}

n_client_Client_cursorPath.signature:
// cursorPath 返回任务 cursor 文件路径（<游标根>/<agentd 命名空间>/<taskID>）。
//
// 为什么放用户主目录而非配置 DataDir：cursor 是协调者侧的本地状态，
// 与配置/数据库文件位置解耦；即使 DataDir 被移动，协调者已看过的进度也不重投。
// 该决策保留，cursordir.go 只是让这个根在不可写时可以降级。
//
// 为什么要 agentd 这一层：文件名只按 taskID 时，两台 agentd 上碰巧同 ID 的
// 任务会共用一个游标文件，互相把对方的进度顶掉。
func (c *Client) cursorPath(taskID string) (string, error) {
	root, err := c.cursorRootDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(root, cursorNamespace(c.baseURL), taskID), nil
}

n_client_Client_doStream.signature:
// doStream 发送带 Bearer token 的流式 GET 请求，返回不关闭 body 的响应。
//
// 为什么不能复用 do：do 不做任何读体/超时假设，但它没有专门的流式语义——
// 而 RenderStream 需要保证响应体不被整体超时掐断（follow 长连接可能挂很久）。
// c.hc 本就没有全局 Timeout（只有拨号超时），直接复用即可；本函数与 do 的
// 区别只在明确「调用方负责消费并 Close body」。
func (c *Client) doStream(ctx context.Context, method, path string) (*http.Response, error) {
	if err := c.checkInit(); err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, nil)
	if err != nil {
		return nil, fmt.Errorf("构造请求 %s: %w", path, err)
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	return c.hc.Do(req)
}

n_client_Client_readCursor.signature:
// readCursor 读取任务 cursor；任何读不出来的情形都返回 0（从头开始）。
func (c *Client) readCursor(taskID string) int64 {
	seq, _ := c.readCursorWithDiag(taskID)
	return seq
}

n_client_Client_readCursorWithDiag.signature:
// readCursorWithDiag 是 readCursor 的可诊断变体。
//
// 返回：
//   - seq: 游标值；读不出来时为 0
//   - reported: 是否属于「游标存在但用不了」并已告警（供测试断言，生产不用）
//
// 为什么要把「文件不存在」与其它错误分开：文件不存在是每个任务第一次 wait 的
// 常态，报它等于每次都喊狼来了；而权限被拒与内容损坏意味着游标存在却用不了，
// 后果是静默从 0 重放全部历史事件——协调者会看到一串早就处理过的旧事件，
// 却没有任何一条信息指向真正的原因。这是 B75 现场的成因。
func (c *Client) readCursorWithDiag(taskID string) (seq int64, reported bool) {
	p, err := c.cursorPath(taskID)
	if err != nil {
		c.log().Warn("游标路径不可用，本次从头开始", "task", taskID, "cause", err)
		return 0, true
	}
	b, err := os.ReadFile(p)
	if err != nil {
		if os.IsNotExist(err) {
			c.log().Debug("cursor 文件不存在，从头开始", "task", taskID, "path", p)
			return 0, false
		}
		c.log().Warn("cursor 存在但读不了，本次将从头重放事件",
			"task", taskID, "path", p, "cause", err)
		return 0, true
	}
	n, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64)
	if err != nil || n < 0 {
		c.log().Warn("cursor 内容损坏，本次将从头重放事件",
			"task", taskID, "path", p, "content", turnTailForLog(string(b)))
		return 0, true
	}
	c.log().Debug("cursor 读取", "task", taskID, "path", p, "seq", n)
	return n, false
}

n_client_Client_reconcileBacklog.signature:
// reconcileBacklog 在建立 WS 连接前对账：拿一次权威快照，判断本机 cursor 之后
// 是否积压了未读事件；有则吐一行摘要并把 cursor 直接推到当前水位。
//
// 参数：
//   - taskID: 完整 UUID
//   - fromSeq: 本机 cursor 当前停在哪
//   - onBacklog: 摘要的消费者（cmd 层写 stdout）；返回非 nil 立即上抛
//
// 返回：
//   - next: WS 应当使用的 from_seq——有积压时是当前水位，否则原样是 fromSeq
//   - terminal: 快照显示任务已 failed，调用方应吐完摘要后正常收尾（返回 nil）
//   - err: 仅当 onBacklog 报错；**网络/HTTP 失败一律不报错**（见下）
//
// 为什么积压事件不拉取而是直接跳过：摘要用的是权威快照，比逐条重放**信息更全**
// ——重放里混着已被审批链答掉的历史工单（补 reply 会 404），而 PendingTickets
// 只含真正还欠的，且每张带完整 Request 原文。
//
// 为什么 Attach 失败是降级而不是报错：摘要是优化不是正确性，对账失败就该退回
// 改动前的逐条重放，绝不能因此中断 follow。永久性（401/404）也不在这里判——
// Client.Attach 的错误是普通 fmt.Errorf 而非 permanentError，isPermanent 认不出
// 它；紧随其后的 WS 握手会用既有的、已被测试覆盖的路径判出同一个结论。判定
// 只留一处，不复制。
func (c *Client) reconcileBacklog(ctx context.Context, taskID string, fromSeq int64,
	onBacklog func(*BacklogSummary) error) (int64, bool, error) {
	c.log().Debug("follow 积压对账开始", "task", taskID, "from_seq", fromSeq)

	snap, err := c.Attach(ctx, taskID)
	if err != nil {
		c.log().Warn("follow 积压对账失败，退回逐条重放", "task", taskID,
			"from_seq", fromSeq, "cause", err)
		return fromSeq, false, nil
	}

	sum := computeBacklog(taskID, fromSeq, snap)
	if sum == nil {
		c.log().Debug("follow 积压对账完成：无积压", "task", taskID, "from_seq", fromSeq)
		return fromSeq, false, nil
	}

	c.log().Info("follow 积压对账：有积压", "task", taskID,
		"from_seq", sum.FromSeq, "to_seq", sum.ToSeq, "missed", sum.Missed,
		"stale", sum.Stale, "actionable", len(sum.Actionable),
		"truncated", sum.MissedTruncated, "state", string(sum.State))

	if berr := onBacklog(sum); berr != nil {
		return fromSeq, false, berr
	}
	if werr := c.writeCursor(taskID, sum.ToSeq); werr != nil {

		c.log().Warn("对账后 cursor 写盘失败", "task", taskID, "seq", sum.ToSeq, "cause", werr)
	}
	return sum.ToSeq, sum.State == proto.TaskStateFailed, nil
}

n_client_Client_streamOnce.signature:
// streamOnce 建立一次 WS 连接并把收到的每一帧交给 onFrame，直到 onFrame 收手或连接结束。
//
// 参数：
//   - fromSeq: 断线续拉起点（服务端据此补发历史事件）
//   - readDeadline: 每次 Read 前调用一次，返回本次读取的**绝对**截止时刻；
//     返回零值表示不设。为什么是绝对时刻而不是时长：空闲要跨重连累计，
//     每次连接都从头计时等于让一个反复断连的对端永远超不了时
//   - onFrame: 每收到一帧调用一次（**含 progress**，过滤由调用方做）
//
// 返回：
//   - nil: onFrame 返回 errStopStream
//   - errArchived: 对端以 StatusNormalClosure 关闭（任务已归档）
//   - ErrIdleTimeout: 读取超过 readDeadline 且外层 ctx 未取消
//   - permanentError / 其他: 拨号或读取失败，由调用方决定是否重连
func (c *Client) streamOnce(ctx context.Context, taskID string, fromSeq int64,
	readDeadline func() time.Time, onFrame func(proto.Event) error) error {
	if err := c.checkInit(); err != nil {
		return err
	}

	wsScheme := "ws"
	if strings.HasPrefix(c.baseURL, "https://") {
		wsScheme = "wss"
	}
	host := strings.TrimPrefix(strings.TrimPrefix(c.baseURL, "http://"), "https://")
	wsURL := wsScheme + "://" + host + "/ws/events?task=" + taskID +
		"&from_seq=" + strconv.FormatInt(fromSeq, 10)

	opts := c.wsDialOptions()
	dialCtx, dialCancel := context.WithTimeout(ctx, dialTimeout)
	conn, resp, err := websocket.Dial(dialCtx, wsURL, opts)
	dialCancel()
	if err != nil {
		if resp != nil && isPermanentStatus(resp.StatusCode) {
			return &permanentError{op: "WS 拨号", code: resp.StatusCode, cause: err}
		}
		if resp != nil {
			return fmt.Errorf("WS 拨号失败 status=%d: %w", resp.StatusCode, err)
		}
		return fmt.Errorf("WS 拨号失败: %w", err)
	}
	c.log().Debug("WS 连接建立", "addr", c.baseURL, "task", taskID, "from_seq", fromSeq)
	defer func() {
		conn.CloseNow()
		c.log().Debug("WS 连接关闭", "addr", c.baseURL, "task", taskID)
	}()

	for {
		readCtx, cancelRead := ctx, context.CancelFunc(func() {})
		if readDeadline != nil {
			if dl := readDeadline(); !dl.IsZero() {
				readCtx, cancelRead = context.WithDeadline(ctx, dl)
			}
		}
		_, b, err := conn.Read(readCtx)

		idleExpired := ctx.Err() == nil && errors.Is(readCtx.Err(), context.DeadlineExceeded)
		cancelRead()
		if err != nil {
			if idleExpired {
				return ErrIdleTimeout
			}
			if websocket.CloseStatus(err) == websocket.StatusNormalClosure {
				return errArchived
			}
			return fmt.Errorf("WS 读取: %w", err)
		}
		var ev proto.Event
		if err := json.Unmarshal(b, &ev); err != nil {

			return fmt.Errorf("WS 事件反序列化: %w", err)
		}
		if err := onFrame(ev); err != nil {
			if errors.Is(err, errStopStream) {
				return nil
			}
			return err
		}
	}
}

n_client_Client_waitOnce.signature:
// waitOnce 建立一次 WS 连接并消费事件，直到返回首个可动作事件或连接失败。
//
// 返回：
//   - 可动作事件；连接失败/断流时返回错误（由 WaitEvent 决定是否重连）
//
// 注意：
//   - 返回错误时调用方凭 fromSeq 重连补拉，已消费的事件不会重复交付（见 WaitEvent doc）
//   - 永久性失败以 permanentError 返回（握手 400/401/403），或原样透传对端的
//     StatusPolicyViolation close（任务不存在）——两者均被 isPermanent 识别，不再重连
//   - 本函数现在是 streamOnce 的薄封装，外部行为与重构前逐字节一致；
//     正常关闭码在 streamOnce 里被识别为 errArchived，它不是永久失败，
//     WaitEvent 仍按断线重连处理（ws_backoff_test 钉住了这条等价性）
func (c *Client) waitOnce(ctx context.Context, taskID string, fromSeq int64, all bool) (*proto.Event, error) {
	var got *proto.Event
	err := c.streamOnce(ctx, taskID, fromSeq, nil, func(ev proto.Event) error {

		if !all && !isDeliverable(ev.Type) {
			c.log().Debug("wait 跳过不可交付事件", "task", taskID, "seq", ev.Seq, "type", ev.Type)
			return nil
		}
		c.log().Info("wait 事件返回", "task", taskID, "seq", ev.Seq, "type", ev.Type)
		got = &ev
		return errStopStream
	})
	if err != nil {
		return nil, err
	}
	return got, nil
}

n_client_Client_writeCursor.signature:
// writeCursor 把 seq 原子写入 cursor 文件（临时文件 + rename）。
//
// 为什么先写临时文件再 rename：直接写目标文件在写盘中途崩溃会留下截断内容，
// 下一次 wait 会把截断文本解析成 0（从头重投全部事件）；rename 保证读到的一定是
// 完整内容——要么旧值要么新值，不存在中间态。
//
// 为什么临时文件必须唯一（L-3）：两个 wait 进程/goroutine 并发写同一任务的
// 游标文件时，固定后缀的 <path>.tmp 会被两边同时打开/截断——先写完者
// rename 掉的是对方可能还没写完的共享文件，目标文件会短暂出现半截内容，对端
// 恰好读到即「读到一半的 tmp」。CreateTemp 同目录生成 O_EXCL 唯一名，rename
// 的始终是「自己写完整并关闭的文件」，并发读保证只看到完整旧值或完整新值。
func (c *Client) writeCursor(taskID string, seq int64) error {
	p, err := c.cursorPath(taskID)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
		return fmt.Errorf("创建 cursor 目录: %w", err)
	}
	f, err := os.CreateTemp(filepath.Dir(p), filepath.Base(p)+"-*.tmp")
	if err != nil {
		return fmt.Errorf("创建临时 cursor 文件: %w", err)
	}
	tmp := f.Name()
	if _, err := f.WriteString(strconv.FormatInt(seq, 10)); err != nil {
		f.Close()
		os.Remove(tmp)
		return fmt.Errorf("写临时 cursor 文件: %w", err)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("关闭临时 cursor 文件: %w", err)
	}
	if err := os.Rename(tmp, p); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("cursor 落盘: %w", err)
	}
	c.log().Debug("cursor 写入", "task", taskID, "path", p, "seq", seq)
	c.sweepStaleCursorTemps(filepath.Dir(p), taskID)
	return nil
}

n_client_turnTailForLog.signature:
// turnTailForLog 把可能很长的损坏内容截到可入日志的长度。
//
// 为什么截断：损坏的 cursor 文件可能是任意内容（磁盘故障写进了别的东西），
// 原样入日志会把一行日志撑成几 MB。
func turnTailForLog(s string) string {
	const max = 64
	if len(s) <= max {
		return s
	}
	return s[:max] + "…"
}

m_ledgerstep_DispatchOpts.signature:
// DispatchOpts 是 Transport 的完整派发请求。PlanPath 已在 ViaTemplate 中
// 读成 PlanB64/PlanName；其余字段与 agentd 的派发协议一一对应。
type DispatchOpts struct {
	Prompt, Branch, Target, Project, Executor, Model, PlanB64, PlanName, Base, ExistingBranch, Discipline string
	// Receiver 是统一接收者名（载体或小队）。空=默认载体。Ticket 0 只声明。
	Receiver string
	// Carrier/Squad 是卡节点已经冻结的执行身份；空=普通派发或旧调用。
	// ledgerstep 只透传，不解析、不准入、不释放。
	Carrier string
	Squad   string
	// HomeDir 是小队派发载体 HOME 的可空透传值；nil=字段缺席，指向空串=显式空值。
	HomeDir *string
	// FrozenTarget 是卡节点冻结的执行物理身份（Binding.Target 的原始机器名）。
	// 与 Target 分工：Target 是路由值，可被 NormalizeTarget 折成本机空串；
	// FrozenTarget 是身份快照，原样透传，不解析、不归一、不校验（B398）。
	// 空=普通派发或旧调用。
	FrozenTarget string
	// B229：DisciplineText 是协调者侧组装好的纪律正文（缝 1 discipline.ResolveDispatch 产物），
	// 随请求下发；执行机收文即用，不再自行解析。DisciplineVersion 是命中的账本
	// 版本号（未点名或临时正文为 0），供快照与回放。Ticket 0 仅声明，接线归实现票。
	DisciplineText    string
	DisciplineVersion int
	// OutputPath 是节点声明路径的确定值，供 transport 审计与测试观察；路径同时已注入 Prompt。
	OutputPath  string
	NewWorktree bool
	// ResolveDefaultBase 标记卡链没有显式基线，需由知道目标仓库路径的 agentd
	// 解析项目默认分支；false 时保持普通派发的 Base/HEAD 语义。
	ResolveDefaultBase bool
	// LocalBaseBranch 标记 Base 是目标机本地的工作分支；目标侧只解析本地 ref，
	// 不得走分支名的远端补拉路径。与 ResolveDefaultBase 互斥。
	LocalBaseBranch bool
}

m_ledgerstep_DispatchResult.signature:
type DispatchResult struct {
	Card	string	`json:"card"`
	Task	string	`json:"task"`
	Node	string	`json:"node,omitempty"`
	// Attempt 是本次节点尝试身份，按契约取返回的 TaskID。
	Attempt	string	`json:"attempt,omitempty"`
	Target	string	`json:"target"`
	Branch	string	`json:"branch"`
	// Base 是本次传给 agentd 的起点分支名；它不是卡的 effective base_branch。
	Base	string	`json:"base"`
	// BaseCommit 是目标 agentd Task.BaseCommit 的原样回传值。
	BaseCommit	string	`json:"base_commit"`
	Template	string	`json:"template"`
	TemplateVersion	int	`json:"template_version"`
	DisciplineName	string	`json:"discipline_name"`
	// DisciplineVersion 是本次派发命中的纪律块账本版本（B229）；未点名/临时正文为 0。
	DisciplineVersion	int	`json:"discipline_version"`
}

m_ledgerstep_Dispatcher.signature:
// Dispatcher 持有模板派发需要的账本、传输和审计 actor。
type Dispatcher struct {
	St        *ledger.Store
	Transport Transport
	// Compensate 在 Transport 已成功返回 task id、但本地快照/挂账或写闸失败时调用。
	// nil 表示未装配；此时仍记录失败轮次但不执行远端动作。
	Compensate DispatchCompensator
	Actor      string
	// HomeDir 是小队绑定载体 HOME 的可空原指针；nil 表示普通派发，指向空串
	// 表示显式不覆盖目标进程 HOME。ledgerstep 不展开、清理或改写该字符串。
	HomeDir *string
	// Carrier/Squad 是卡节点起源侧已冻结的执行身份；普通派发保持空值。
	Carrier string
	Squad   string
	// FrozenTarget 是卡节点起源侧已冻结的执行物理身份（Binding.Target 原始机器名）。
	// 与 ViaTemplate 的 Target 分工：Target 参与路由归一，FrozenTarget 不归一，
	// 原样进入 DispatchOpts 供接收端 AdmitFrozen（B398）。空=普通派发或旧调用。
	FrozenTarget string
	// NormalizeTarget 把调用方已确认的自机登记名归一成空串；nil 等价于恒等
	// 函数。未知目标名不得在此处改写，目标身份判断归组装点负责。
	NormalizeTarget func(target string) string

	// B229 缝 1 产物（数据字段，不是解析函数）：调用方装配时经
	// discipline.ResolveDispatch 解析好的纪律正文与账本版本号。未点名模板的
	// 调用方传纯平台层正文、版本 0。ViaTemplate 原样透传进 DispatchOpts 与
	// dispatched 快照——ledgerstep 不 import discipline：组装点唯一在 d_policy
	// （B229 契约 §4.5），本包零新增 import，解析动作归调用方装配处。
	DisciplineText    string
	DisciplineVersion int
}

m_ledgerstep_TemplateDispatch.signature:
type TemplateDispatch struct {
	Template	string
	Target		string
	// Receiver 是已由调用方解析的统一接收者名；空值沿用默认载体语义。
	Receiver	string
	// Node 是工作流节点名；普通 card dispatch 为空。
	Node			string
	PlanPath		string
	DisciplineOverride	string
	// WriteGate 在 Transport 成功后、原子账本事务写入前调用；nil 表示不设闸。
	// 运行节点用它阻止失去运行锁后的挂账与 dispatched 快照写入。
	WriteGate	func() bool
	// ExecutorOverride / ModelOverride 是调用方对模板的单字段覆盖；空 = 用模板的。
	// 当 ExecutorOverride 真的改变有效 executor 且 ModelOverride 为空时，
	// ViaTemplate 会清掉下层模型；只显式重述同一个 executor 不改变模型。
	ExecutorOverride	string
	ModelOverride		string
	// CarryCardContext 为真时把卡上下文段拼进 prompt（来自节点的同名开关）。
	CarryCardContext	bool
	// PurposeOverride 覆盖模板的派发用途；空 = 用模板的。
	// 用途决定分支命名、审阅基线、工作分支归属与轮次挂号四件事，见
	// ledger.NodeOverride.Purpose 的注释。
	PurposeOverride	string
	// OmitAcceptance 为真时不把整卡验收判据注入 prompt（来自节点的同名开关）。
	OmitAcceptance	bool
	// Extra 是本次派发的临时补充说明，可为空。
	Extra	string
	// OutputPath 是本节点声明路径在协调者侧按本轮派发日期渲染后的确定值。
	// 它独立于 CarryCardContext：即使不携带卡上下文，执行者仍必须收到该法定路径。
	OutputPath	string
}

n_ledgerstep_Dispatcher_ViaTemplate.signature:
// ViaTemplate 按模板把一张卡派出去。
//
// 参数：c 卡；req 模板名、目标机、可选 plan 路径与纪律块角色名覆盖。
// 返回：派发结果（含 task id、起点分支、agentd Task.BaseCommit、模板版本、纪律块角色名）。
//
// 注意：不含协调者席位语义。实现类与环节派发都只负责派任务；运行互斥由
// 节点编排的 RunLock 负责，席位由 bind/coordinate/rebind 命令管理。
// 本次只调用一次 Transport；快照和五列挂账在一个事务内完成，不因本地落账
// 失败重派第二个 task。已创建 task 的失败回收由 Compensate 注入，不删除分支。
//
// req.PlanPath 按调用方进程的 CWD 解析。agentd 一侧永远传空串：
// 浏览器里没有 plan 文件，实现类派发也不从界面走。
func (d *Dispatcher) ViaTemplate(ctx context.Context, c ledger.Card, req TemplateDispatch) (DispatchResult, error) {
	var zero DispatchResult
	tpl, err := d.St.GetTemplate(req.Template, 0)
	if err != nil {
		slog.Default().Warn("取模板失败", "card", c.ID, "template", req.Template, "cause", err)
		return zero, fmt.Errorf("取模板: %w", err)
	}
	// 有效目标机与纪律角色名：请求覆盖 > 模板缺省。两个调用方装配处的缝 1
	// 解析必须与这里完全同序（共用 PreflightDiscipline → disciplineAndTarget），
	// 各抄一份迟早漂移——探错目标机的拒发闸比没有闸更危险。
	target := req.Target
	if target == "" {
		target = tpl.Def.Target
	}
	rawTarget := target
	if d.NormalizeTarget != nil {
		target = d.NormalizeTarget(target)
	}
	disciplineName := tpl.Def.Discipline
	if req.DisciplineOverride != "" {
		disciplineName = req.DisciplineOverride
	}
	slog.Default().Info("模板派发目标已归一", "card", c.ID, "template", req.Template,
		"raw_target", rawTarget, "target", target, "frozen_target", d.FrozenTarget)

	// 有效用途：节点覆盖优先于模板。下面**所有**按用途裁决的地方都读它，
	// 不再直接读取模板用途字段——漏掉任何一处都会让节点只对了一半（例如分支
	// 名对了但快照里记的还是模板用途，WorkBranch 于是把审阅分支当成工作分支）。
	templateDef := tpl.Def
	purpose := templateDef.Purpose
	if req.PurposeOverride != "" {
		purpose = req.PurposeOverride
	}

	// WorkBranch 同时返回分支和上次目标机；这两个值必须来自同一条非审阅
	// dispatched 快照，才能可靠判断本次是否仍在持有该私有工作分支的机器上。
	// 跨机时在 Transport 之前拒绝，避免静默退回卡基线并丢掉上一轮产出。
	workInfo, workErr := d.St.WorkBranch(c.ID)
	hasWorkBranch := workErr == nil
	if workErr != nil && !errors.Is(workErr, ledger.ErrNotFound) {
		slog.Default().Error("读取卡工作分支失败", "card", c.ID, "target", target,
			"previous_target", "", "branch", "", "cause", workErr)
		return zero, fmt.Errorf("取卡工作分支: %w", workErr)
	}
	previousTarget := ""
	if hasWorkBranch {
		previousTarget = workInfo.Target
		if d.NormalizeTarget != nil {
			previousTarget = d.NormalizeTarget(previousTarget)
		}
	}
	originReady := false
	if hasWorkBranch && previousTarget != target {
		published, pubErr := d.St.WorkBranchPublished(c.ID, workInfo.Branch)
		if pubErr != nil {
			slog.Default().Error("读取工作分支 origin 发布失败", "card", c.ID,
				"branch", workInfo.Branch, "cause", pubErr)
			return zero, fmt.Errorf("取工作分支 origin 发布: %w", pubErr)
		}
		if !published {
			slog.Default().Warn("工作分支跨目标机且未发布 origin，拒绝接续", "card", c.ID,
				"branch", workInfo.Branch, "previous_target", previousTarget, "target", target,
				"cause", "目标机身份不一致且 origin 未见该分支")
			return zero, fmt.Errorf("工作分支只存在于创建它的那台机器：上次目标机 %q，本次目标机 %q；请先在上一台 git push origin %s（失败则 needs_human）。日常路径不使用 --base",
				previousTarget, target, workInfo.Branch)
		}
		originReady = true
		slog.Default().Info("工作分支已在 origin，跨机接续", "card", c.ID,
			"branch", workInfo.Branch, "previous_target", previousTarget, "target", target)
	}

	// 判据被收起时不留空冒号：模板正文里「验收判据：{{ACCEPT}}」后面跟一片
	// 空白，比说明白更让执行者困惑。替换值已经是完整句——模板 {{ACCEPT}} 后面
	// 不要再跟「这是整卡的最终验收判据」：那句是 B182 的失败缓解，omit 时会
	// 跟本句并置成病句（B197），且没挡住 plan 节点写实现。
	acceptance := c.AcceptanceCriteria
	if req.OmitAcceptance {
		acceptance = "（本节点不注入整卡验收判据——那是实现级的最终判据；本节点的产出物与 pass 依据以纪律块为准）"
	}
	body := strings.NewReplacer(
		"{{TITLE}}", c.Title,
		"{{CARD}}", c.ID,
		"{{ACCEPT}}", acceptance,
	).Replace(tpl.Def.Prompt)

	// 审阅轮跑在卡的工作分支上：审阅是只读的，开自己的分支既没意义，又会
	// 让同一张卡的第二轮撞上第一轮的同名分支（判据② 的 3 轮封顶因此走不到
	// 第二轮——2026-08-19 真机实测 fatal: a branch named ... already exists）
	branch := fmt.Sprintf("%s/%s-%s", tpl.Def.BranchPrefix, c.ID, purpose)
	existingBranch := ""
	if purpose == ledger.PurposeReview {
		if !hasWorkBranch {
			return zero, fmt.Errorf("审阅轮取工作分支: %w", workErr)
		}
		// 审阅每轮开一条指向工作分支当前提交的一次性分支。三个约束叠出这个形态：
		// ① 不能复用固定名 cards/<卡>-review——第二轮撞名，判据② 的 3 轮封顶
		//    走不到第二轮；② 不能直接检出工作分支——实现任务的工作树还占着它，
		//    git 不许两个工作树检出同一分支；③ 审阅要看的是工作分支的代码，
		//    所以起点必须是它的当前提交（base=work）
		round, err := d.St.ReviewRounds(c.ID)
		if err != nil {
			return zero, fmt.Errorf("审阅轮取轮次: %w", err)
		}
		branch = fmt.Sprintf("%s/%s-review-%d", tpl.Def.BranchPrefix, c.ID, round+1)
	} else {
		// 非审阅节点的重跑同样会撞分支名——同一张卡第二次从同 purpose 模板
		// 派发时，目标机上第一轮分支还在，git 拒绝创建同名分支（与审阅轮
		// 2026-08-19 真机实测同一形态）。解法与审阅一致：按「同 purpose 已派
		// 几次」挂号。首轮保持无后缀，存量卡的分支命名不变。
		rounds, err := d.St.PurposeRounds(c.ID, purpose)
		if err != nil {
			return zero, fmt.Errorf("取 %s 轮次: %w", purpose, err)
		}
		if rounds > 0 {
			branch = fmt.Sprintf("%s-%d", branch, rounds+1)
			slog.Default().Info("重跑轮分支挂号", "card", c.ID,
				"purpose", purpose, "round", rounds+1, "branch", branch)
		}
	}
	base, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取有效基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", "", "cause", err)
		return zero, fmt.Errorf("取有效基线: %w", err)
	}
	localBaseBranch := false
	if hasWorkBranch {
		base = workInfo.Branch // 后续节点从工作分支起，不是从卡合并基线起
		if !originReady {
			localBaseBranch = true
		}
	}
	resolveDefaultBase := base == ""
	// 三段拼装要用到有效基线，所以必须排在 base 算完之后。审阅轮的 base 被
	// 换成了工作分支，但卡上下文里要写的是**卡的**基线（合并目标），两者不同，
	// 因此这里重新取一次而不是复用上面的 base。
	cardBase, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取卡上下文基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", branch, "cause", err)
		return zero, fmt.Errorf("取卡上下文基线: %w", err)
	}
	prompt := buildPrompt(body, c, cardBase, req.CarryCardContext, req.OmitAcceptance, req.Extra, req.OutputPath)
	model := ""
	if tpl.Def.ModelByTarget != nil {
		model = tpl.Def.ModelByTarget[target]
	}
	executor := tpl.Def.Executor
	if req.ExecutorOverride != "" && req.ExecutorOverride != tpl.Def.Executor {
		executor = req.ExecutorOverride
		// 模型是执行器的同层伴随覆盖。换执行器时不能把模板声明的模型
		// 带给新执行器；空值交给新执行器自身的默认模型。这里按“有效
		// executor 是否变化”判定，与 agentd Manager.resolveModel 的边界
		// 注释同源：显式写出默认 executor 仍照常套用配置模型。
		model = ""
	} else if req.ExecutorOverride != "" {
		executor = req.ExecutorOverride
	}
	if req.ModelOverride != "" {
		model = req.ModelOverride
	}
	var planB64, planName string
	if req.PlanPath != "" {
		content, err := os.ReadFile(req.PlanPath)
		if err != nil {
			return zero, fmt.Errorf("读 plan %s: %w", req.PlanPath, err)
		}
		planB64 = base64.StdEncoding.EncodeToString(content)
		planName = filepath.Base(req.PlanPath)
	}
	slog.Default().Info("按模板派发",
		"card", c.ID, "node", req.Node, "template", req.Template, "target", target,
		"receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"frozen_target", d.FrozenTarget,
		"executor", executor, "model", model, "discipline", disciplineName,
		"discipline_version", d.DisciplineVersion,
		"discipline_bytes", len(d.DisciplineText),
		"purpose", purpose, "purpose_overridden", req.PurposeOverride != "",
		"omit_acceptance", req.OmitAcceptance,
		"branch", branch, "base", base,
		"resolve_default_base", resolveDefaultBase,
		"carry_card_context", req.CarryCardContext, "has_extra", strings.TrimSpace(req.Extra) != "",
		"output_path", req.OutputPath,
		"prompt_bytes", len(prompt))
	slog.Default().Info("派发前已确定节点产出路径", "card", c.ID, "node", req.Node,
		"template", req.Template, "target", target, "receiver", req.Receiver,
		"output_path", req.OutputPath)
	taskID, baseCommit, err := d.Transport(ctx, DispatchOpts{
		Prompt: prompt, Branch: branch, Target: target, Project: c.Project,
		Executor: executor, Model: model, PlanB64: planB64,
		Receiver:     req.Receiver,
		Carrier:      d.Carrier,
		Squad:        d.Squad,
		HomeDir:      d.HomeDir,
		FrozenTarget: d.FrozenTarget,
		OutputPath:   req.OutputPath,
		PlanName:     planName, Base: base, NewWorktree: true,
		ExistingBranch: existingBranch, Discipline: disciplineName,
		// B229：调用方经缝 1 解析好的正文与版本，原样下发（§3.1 未点名也带平台层）。
		DisciplineText:     d.DisciplineText,
		DisciplineVersion:  d.DisciplineVersion,
		ResolveDefaultBase: resolveDefaultBase,
		LocalBaseBranch:    localBaseBranch,
	})
	if err != nil {
		slog.Default().Warn("模板派发传输失败", "card", c.ID, "node", req.Node,
			"attempt", "", "target", target, "task", "", "seq", 0,
			"type", ledger.EvDispatched, "branch", branch, "base", base, "cause", err)
		return zero, fmt.Errorf("派发: %w", err)
	}
	slog.Default().Info("模板派发传输已返回", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad,
		"base", base, "base_commit", baseCommit)
	slog.Default().Info("模板派发已裁定纪律块角色", "card", c.ID, "node", req.Node,
		"template", req.Template, "discipline", disciplineName,
		"overridden", req.DisciplineOverride != "")
	snapshotBranch := branch
	if snapshotBranch == "" {
		snapshotBranch = existingBranch
	}
	// 先落快照再挂账：镜像对账能在 LinkTask 可见前取得 Node/Attempt 投影，
	// 避免空身份事件先消耗 source watermark 后无法用新身份重放。两步在账本
	// 同一事务内完成，挂账失败时事务回消快照；已创建 task 交给注入的
	// Compensate best-effort 回收，失败不改变本地原始错误。
	if req.WriteGate != nil && !req.WriteGate() {
		originalErr := fmt.Errorf("派发落账被拒：%w", ErrWriteGateClosed)
		slog.Default().Warn("失去写权，停止派发快照与挂账", "card", c.ID,
			"node", req.Node, "attempt", taskID, "target", target, "task", taskID,
			"seq", 0, "type", ledger.EvDispatched, "cause", originalErr)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	snapshot := ledger.DispatchSnapshot{
		Template: tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion: d.DisciplineVersion,
		Target:            target, TaskID: taskID, Branch: snapshotBranch,
		Node: req.Node, Attempt: taskID,
		Base: base, BaseCommit: baseCommit,
		Executor: executor, Model: model,
		Purpose: purpose, PlanPath: req.PlanPath, Actor: d.Actor,
	}
	slog.Default().Info("模板派发快照与挂账落账开始", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "snapshot", snapshot)
	snapshotSeq, linkSeq, err := d.St.RecordDispatchAndLinkTask(c.ID, snapshot)
	if err != nil {
		slog.Default().Warn("模板派发快照与挂账落账失败", "card", c.ID, "node", req.Node,
			"attempt", taskID, "target", target, "task", taskID, "seq", snapshotSeq,
			"type", ledger.EvDispatched, "link_seq", linkSeq, "cause", err)
		originalErr := fmt.Errorf("快照与挂账落账: %w", err)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	slog.Default().Info("模板派发快照与挂账落账完成", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", linkSeq,
		"type", ledger.EvComment, "snapshot_seq", snapshotSeq, "snapshot", snapshot)
	slog.Default().Info("模板派发完成", "card", c.ID, "node", req.Node, "template", tpl.Name,
		"attempt", taskID, "task", taskID, "target", target, "receiver", req.Receiver,
		"carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"frozen_target", d.FrozenTarget,
		"executor", executor, "model", model, "branch", snapshotBranch, "discipline", disciplineName)
	return DispatchResult{
		Card: c.ID, Task: taskID, Target: target, Branch: snapshotBranch,
		Node: req.Node, Attempt: taskID,
		Base: base, BaseCommit: baseCommit,
		Template: tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion: d.DisciplineVersion,
	}, nil
}

n_ledgerstep_Dispatcher_ViaTemplate.signatureOld:
// ViaTemplate 按模板把一张卡派出去。
//
// 参数：c 卡；req 模板名、目标机、可选 plan 路径与纪律块角色名覆盖。
// 返回：派发结果（含 task id、起点分支、agentd Task.BaseCommit、模板版本、纪律块角色名）。
//
// 注意：不含协调者席位语义。实现类与环节派发都只负责派任务；运行互斥由
// 节点编排的 RunLock 负责，席位由 bind/coordinate/rebind 命令管理。
// 本次只调用一次 Transport；快照和五列挂账在一个事务内完成，不因本地落账
// 失败重派第二个 task。已创建 task 的失败回收由 Compensate 注入，不删除分支。
//
// req.PlanPath 按调用方进程的 CWD 解析。agentd 一侧永远传空串：
// 浏览器里没有 plan 文件，实现类派发也不从界面走。
func (d *Dispatcher) ViaTemplate(ctx context.Context, c ledger.Card, req TemplateDispatch) (DispatchResult, error) {
	var zero DispatchResult
	tpl, err := d.St.GetTemplate(req.Template, 0)
	if err != nil {
		slog.Default().Warn("取模板失败", "card", c.ID, "template", req.Template, "cause", err)
		return zero, fmt.Errorf("取模板: %w", err)
	}

	target := req.Target
	if target == "" {
		target = tpl.Def.Target
	}
	rawTarget := target
	if d.NormalizeTarget != nil {
		target = d.NormalizeTarget(target)
	}
	disciplineName := tpl.Def.Discipline
	if req.DisciplineOverride != "" {
		disciplineName = req.DisciplineOverride
	}
	slog.Default().Info("模板派发目标已归一", "card", c.ID, "template", req.Template,
		"raw_target", rawTarget, "target", target)

	templateDef := tpl.Def
	purpose := templateDef.Purpose
	if req.PurposeOverride != "" {
		purpose = req.PurposeOverride
	}

	workInfo, workErr := d.St.WorkBranch(c.ID)
	hasWorkBranch := workErr == nil
	if workErr != nil && !errors.Is(workErr, ledger.ErrNotFound) {
		slog.Default().Error("读取卡工作分支失败", "card", c.ID, "target", target,
			"previous_target", "", "branch", "", "cause", workErr)
		return zero, fmt.Errorf("取卡工作分支: %w", workErr)
	}
	previousTarget := ""
	if hasWorkBranch {
		previousTarget = workInfo.Target
		if d.NormalizeTarget != nil {
			previousTarget = d.NormalizeTarget(previousTarget)
		}
	}
	originReady := false
	if hasWorkBranch && previousTarget != target {
		published, pubErr := d.St.WorkBranchPublished(c.ID, workInfo.Branch)
		if pubErr != nil {
			slog.Default().Error("读取工作分支 origin 发布失败", "card", c.ID,
				"branch", workInfo.Branch, "cause", pubErr)
			return zero, fmt.Errorf("取工作分支 origin 发布: %w", pubErr)
		}
		if !published {
			slog.Default().Warn("工作分支跨目标机且未发布 origin，拒绝接续", "card", c.ID,
				"branch", workInfo.Branch, "previous_target", previousTarget, "target", target,
				"cause", "目标机身份不一致且 origin 未见该分支")
			return zero, fmt.Errorf("工作分支只存在于创建它的那台机器：上次目标机 %q，本次目标机 %q；请先在上一台 git push origin %s（失败则 needs_human）。日常路径不使用 --base",
				previousTarget, target, workInfo.Branch)
		}
		originReady = true
		slog.Default().Info("工作分支已在 origin，跨机接续", "card", c.ID,
			"branch", workInfo.Branch, "previous_target", previousTarget, "target", target)
	}

	acceptance := c.AcceptanceCriteria
	if req.OmitAcceptance {
		acceptance = "（本节点不注入整卡验收判据——那是实现级的最终判据；本节点的产出物与 pass 依据以纪律块为准）"
	}
	body := strings.NewReplacer(
		"{{TITLE}}", c.Title,
		"{{CARD}}", c.ID,
		"{{ACCEPT}}", acceptance,
	).Replace(tpl.Def.Prompt)

	branch := fmt.Sprintf("%s/%s-%s", tpl.Def.BranchPrefix, c.ID, purpose)
	existingBranch := ""
	if purpose == ledger.PurposeReview {
		if !hasWorkBranch {
			return zero, fmt.Errorf("审阅轮取工作分支: %w", workErr)
		}

		round, err := d.St.ReviewRounds(c.ID)
		if err != nil {
			return zero, fmt.Errorf("审阅轮取轮次: %w", err)
		}
		branch = fmt.Sprintf("%s/%s-review-%d", tpl.Def.BranchPrefix, c.ID, round+1)
	} else {

		rounds, err := d.St.PurposeRounds(c.ID, purpose)
		if err != nil {
			return zero, fmt.Errorf("取 %s 轮次: %w", purpose, err)
		}
		if rounds > 0 {
			branch = fmt.Sprintf("%s-%d", branch, rounds+1)
			slog.Default().Info("重跑轮分支挂号", "card", c.ID,
				"purpose", purpose, "round", rounds+1, "branch", branch)
		}
	}
	base, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取有效基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", "", "cause", err)
		return zero, fmt.Errorf("取有效基线: %w", err)
	}
	localBaseBranch := false
	if hasWorkBranch {
		base = workInfo.Branch
		if !originReady {
			localBaseBranch = true
		}
	}
	resolveDefaultBase := base == ""

	cardBase, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取卡上下文基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", branch, "cause", err)
		return zero, fmt.Errorf("取卡上下文基线: %w", err)
	}
	prompt := buildPrompt(body, c, cardBase, req.CarryCardContext, req.OmitAcceptance, req.Extra, req.OutputPath)
	model := ""
	if tpl.Def.ModelByTarget != nil {
		model = tpl.Def.ModelByTarget[target]
	}
	executor := tpl.Def.Executor
	if req.ExecutorOverride != "" && req.ExecutorOverride != tpl.Def.Executor {
		executor = req.ExecutorOverride

		model = ""
	} else if req.ExecutorOverride != "" {
		executor = req.ExecutorOverride
	}
	if req.ModelOverride != "" {
		model = req.ModelOverride
	}
	var planB64, planName string
	if req.PlanPath != "" {
		content, err := os.ReadFile(req.PlanPath)
		if err != nil {
			return zero, fmt.Errorf("读 plan %s: %w", req.PlanPath, err)
		}
		planB64 = base64.StdEncoding.EncodeToString(content)
		planName = filepath.Base(req.PlanPath)
	}
	slog.Default().Info("按模板派发",
		"card", c.ID, "node", req.Node, "template", req.Template, "target", target,
		"receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"executor", executor, "model", model, "discipline", disciplineName,
		"discipline_version", d.DisciplineVersion,
		"discipline_bytes", len(d.DisciplineText),
		"purpose", purpose, "purpose_overridden", req.PurposeOverride != "",
		"omit_acceptance", req.OmitAcceptance,
		"branch", branch, "base", base,
		"resolve_default_base", resolveDefaultBase,
		"carry_card_context", req.CarryCardContext, "has_extra", strings.TrimSpace(req.Extra) != "",
		"output_path", req.OutputPath,
		"prompt_bytes", len(prompt))
	slog.Default().Info("派发前已确定节点产出路径", "card", c.ID, "node", req.Node,
		"template", req.Template, "target", target, "receiver", req.Receiver,
		"output_path", req.OutputPath)
	taskID, baseCommit, err := d.Transport(ctx, DispatchOpts{
		Prompt:	prompt, Branch: branch, Target: target, Project: c.Project,
		Executor:	executor, Model: model, PlanB64: planB64,
		Receiver:	req.Receiver,
		Carrier:	d.Carrier,
		Squad:		d.Squad,
		HomeDir:	d.HomeDir,
		OutputPath:	req.OutputPath,
		PlanName:	planName, Base: base, NewWorktree: true,
		ExistingBranch:	existingBranch, Discipline: disciplineName,

		DisciplineText:		d.DisciplineText,
		DisciplineVersion:	d.DisciplineVersion,
		ResolveDefaultBase:	resolveDefaultBase,
		LocalBaseBranch:	localBaseBranch,
	})
	if err != nil {
		slog.Default().Warn("模板派发传输失败", "card", c.ID, "node", req.Node,
			"attempt", "", "target", target, "task", "", "seq", 0,
			"type", ledger.EvDispatched, "branch", branch, "base", base, "cause", err)
		return zero, fmt.Errorf("派发: %w", err)
	}
	slog.Default().Info("模板派发传输已返回", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad,
		"base", base, "base_commit", baseCommit)
	slog.Default().Info("模板派发已裁定纪律块角色", "card", c.ID, "node", req.Node,
		"template", req.Template, "discipline", disciplineName,
		"overridden", req.DisciplineOverride != "")
	snapshotBranch := branch
	if snapshotBranch == "" {
		snapshotBranch = existingBranch
	}

	if req.WriteGate != nil && !req.WriteGate() {
		originalErr := fmt.Errorf("派发落账被拒：%w", ErrWriteGateClosed)
		slog.Default().Warn("失去写权，停止派发快照与挂账", "card", c.ID,
			"node", req.Node, "attempt", taskID, "target", target, "task", taskID,
			"seq", 0, "type", ledger.EvDispatched, "cause", originalErr)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	snapshot := ledger.DispatchSnapshot{
		Template:	tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion:	d.DisciplineVersion,
		Target:			target, TaskID: taskID, Branch: snapshotBranch,
		Node:	req.Node, Attempt: taskID,
		Base:	base, BaseCommit: baseCommit,
		Executor:	executor, Model: model,
		Purpose:	purpose, PlanPath: req.PlanPath, Actor: d.Actor,
	}
	slog.Default().Info("模板派发快照与挂账落账开始", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "snapshot", snapshot)
	snapshotSeq, linkSeq, err := d.St.RecordDispatchAndLinkTask(c.ID, snapshot)
	if err != nil {
		slog.Default().Warn("模板派发快照与挂账落账失败", "card", c.ID, "node", req.Node,
			"attempt", taskID, "target", target, "task", taskID, "seq", snapshotSeq,
			"type", ledger.EvDispatched, "link_seq", linkSeq, "cause", err)
		originalErr := fmt.Errorf("快照与挂账落账: %w", err)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	slog.Default().Info("模板派发快照与挂账落账完成", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", linkSeq,
		"type", ledger.EvComment, "snapshot_seq", snapshotSeq, "snapshot", snapshot)
	slog.Default().Info("模板派发完成", "card", c.ID, "node", req.Node, "template", tpl.Name,
		"attempt", taskID, "task", taskID, "target", target, "receiver", req.Receiver,
		"carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"executor", executor, "model", model, "branch", snapshotBranch, "discipline", disciplineName)
	return DispatchResult{
		Card:	c.ID, Task: taskID, Target: target, Branch: snapshotBranch,
		Node:	req.Node, Attempt: taskID,
		Base:	base, BaseCommit: baseCommit,
		Template:	tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion:	d.DisciplineVersion,
	}, nil
}

n_ledgerstep_Dispatcher_compensateFailed.signature:
// compensateFailedDispatch 记录已创建 task 的耗费轮次并执行一次注入补偿。
// 失败轮次独立于 card_tasks：后者随失败的快照事务回滚，若复用它会让重试再次
// 使用仍留在执行机上的首轮分支名。副作用失败只记日志，保留 ViaTemplate 原错。
func (d *Dispatcher) compensateFailedDispatch(
	ctx context.Context,
	card ledger.Card,
	purpose, target, taskID string,
	originalErr error,
) {
	logger := slog.Default().With("card", card.ID, "purpose", purpose,
		"target", target, "task", taskID)
	logger.Warn("模板派发记录失败，登记耗费轮次", "cause", originalErr)
	if err := d.St.RecordDispatchRound(card.ID, purpose); err != nil {
		logger.Error("派发耗费轮次落账失败，保留原始错误", "cause", err)
	}
	if d.Compensate == nil {
		logger.Warn("派发补偿钩子未装配")
		return
	}
	logger.Info("派发失败补偿开始")
	if err := d.Compensate(ctx, target, taskID); err != nil {
		logger.Error("派发失败补偿失败，保留原始错误", "cause", err)
		return
	}
	logger.Info("派发失败补偿完成")
}

n_ledgerstep_PreflightDiscipline.signature:
// PreflightDiscipline 以与 ViaTemplate 完全相同的裁决顺序算出一次模板派发的
// 有效（纪律角色名，目标机），供调用方在装配 Dispatcher 前完成缝 1 解析：
// 名字经账本 lookup 取正文、目标机探 Status 拿能力位，一并交给
// discipline.ResolveDispatch 产出正文三元组，再填进 Dispatcher 数据字段。
//
// 参数：st 账本；templateName 模板名；overrideName 调用方角色覆盖（空=不覆盖）；
// reqTarget 调用方目标机覆盖（空=用模板的）。
// 返回：有效角色名与目标机。target 为空表示「模板与请求都没定目标机」——这是
// 纯计算结果不是错误，如何处置（提前拒绝 / 放给 ViaTemplate 的既有失败路径）
// 由调用方按自己的同步语义决定；模板取不到时返回错误。
//
// 为什么导出：有效值依赖「请求覆盖 > 模板缺省」这套回退顺序，本包内
// ViaTemplate 与这里是唯一两处消费点且共用同一私有实现；调用方绕开它
// 自行推导就会与实际派发漂移。
func PreflightDiscipline(st *ledger.Store, templateName, overrideName, reqTarget string) (name, target string, err error) {
	tpl, err := st.GetTemplate(templateName, 0)
	if err != nil {
		return "", "", fmt.Errorf("取模板: %w", err)
	}
	name, target = disciplineAndTarget(tpl.Def, overrideName, reqTarget)
	return name, target, nil
}

n_ledgerstep_buildPrompt.signature:
// buildPrompt 把 executor 收到的 prompt 按三段拼起来。
//
// 参数：
//   - body:  模板正文（占位符已替换完）
//   - c:     卡
//   - base:  卡的有效基线分支，可为空
//   - carry: 是否拼入卡上下文段（节点的 CarryCardContext 开关）
//   - omitAccept: 是否**不**注入整卡验收判据（节点的 OmitAcceptance 开关）
//   - extra: 本次派发的临时补充说明，可为空
//   - outputPath: 本节点声明路径；独立于 carry，即使不带卡上下文也必须注入。
//     这是机器精确匹配键；日期前缀只作为历史文件提示，不是合法变体。
//
// 返回：拼好的 prompt。三段之间用空行分隔，缺席的段不留空标题。
//
// why 分三段而不是全塞进模板：模板是**复用**的（同一份审阅模板给所有卡用），
// 卡上下文是**每张卡不同的事实**，补充说明是**这一次才有的话**。混在一起就
// 只能靠占位符硬塞，而占位符加一个就要改所有模板。
//
// 注意：**这里绝不拼纪律块正文**。正文由调用方经缝 1 解析后走 DispatchOpts
// 的 DisciplineText 独立通道下发；两份纪律同场会让审阅的「只读」被实现块的
// 「完成即 commit」推翻（2026-08-19 真机出过一次）。
func buildPrompt(body string, c ledger.Card, base string, carry, omitAccept bool, extra, outputPath string) string {
	sections := []string{body}
	if carry {
		var b strings.Builder
		b.WriteString("## 本卡上下文\n\n")
		fmt.Fprintf(&b, "- 卡号：%s\n", c.ID)
		fmt.Fprintf(&b, "- 标题：%s\n", c.Title)
		if base != "" {

			fmt.Fprintf(&b, "- 有效基线分支：%s（本卡的合并目标以此为准，不要越过它碰别的分支）\n", base)
		} else {
			b.WriteString("- 有效基线分支：（未设置，需要合并时先向协调者确认，不要自行假定 main）\n")
		}

		if c.AcceptanceCriteria != "" && !omitAccept {
			fmt.Fprintf(&b, "- 验收判据：\n%s\n", indentLines(c.AcceptanceCriteria, "  "))
		}
		if len(c.Attachments) > 0 {
			b.WriteString("- 附件（仓内相对路径）：\n")
			for _, att := range c.Attachments {
				fmt.Fprintf(&b, "  - %s: %s\n", att.Kind, att.Path)
			}
		}
		sections = append(sections, strings.TrimRight(b.String(), "\n"))
	}
	if strings.TrimSpace(extra) != "" {
		sections = append(sections, "## 本次补充\n\n"+strings.TrimSpace(extra))
	}
	if strings.TrimSpace(outputPath) != "" {
		sections = append(sections,
			"## 本节点产出物\n\n- 法定路径："+outputPath+
				"\n- 请把本节点产出物写到该路径，不要另起文件名。"+
				"不要加日期前缀；带 YYYY-MM-DD- 的是历史文件，不是本节点法定产出。")
	}
	return strings.Join(sections, "\n\n")
}

n_ledgerstep_disciplineAndTarget.signature:
// disciplineAndTarget 返回一次模板派发的有效（纪律角色名，目标机）：
// 请求覆盖优先，模板缺省兜底。ViaTemplate 与 PreflightDiscipline 必须共用
// 这一份实现——调用方的缝 1 解析若与派发时的裁决漂移，探活会打错机器、
// 正文会配错名字，拒发闸反而变成事故源。
func disciplineAndTarget(def ledger.TemplateDef, overrideName, reqTarget string) (name, target string) {
	name = def.Discipline
	if overrideName != "" {
		name = overrideName
	}
	target = reqTarget
	if target == "" {
		target = def.Target
	}
	return name, target
}

n_ledgerstep_indentLines.signature:
// indentLines 给多行文本每行加前缀，让验收判据在 markdown 列表下缩进对齐。
func indentLines(s, prefix string) string {
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	for i, line := range lines {
		lines[i] = prefix + line
	}
	return strings.Join(lines, "\n")
}
